func (h *levelHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		h.getLevel(w, r)
	case "PUT":
		h.putLevel(w, r)
	default:
		h.error(w, "Only GET and PUT are supported.", http.StatusMethodNotAllowed)
	}
